{
  "investigate": [
    {
      "tool": "sql",
      "query": "SELECT service, used_mb, quota_mb FROM storage WHERE service = 'invoice-agent'",
      "why": "Check if invoice-agent has disk quota issues since it writes invoice files and its extraction rate dropped"
    }
  ],
  "hypotheses": [
    {
      "service": "worker",
      "kind": "resource_exhaustion",
      "mechanism": "Worker process exceeded its disk quota preventing it from writing invoice files, causing message retries and dead letters",
      "supporting": ["E14", "E15", "E33"],
      "refuting": [],
      "explains": ["M2_error_burst", "M3_dead_letters", "E2", "E4", "E7", "E8", "E9", "E13", "E14", "E15"],
      "repair_plan": [
        {"action": "restart_service", "params": {"service": "worker"}}
      ]
    },
    {
      "service": "sync-job",
      "kind": "resource_exhaustion", 
      "mechanism": "Sync-job process exceeded its disk quota preventing ledger export writes, causing sync failures",
      "supporting": ["E16", "E33"],
      "refuting": [],
      "explains": ["E3", "E6", "E16"],
      "repair_plan": [
        {"action": "restart_service", "params": {"service": "sync-job"}}
      ]
    }
  ],
  "summary": "Disk quota exhaustion in both worker and sync-job services causing processing failures and dead letters."
}
